// Unsound under mod for general inputs; shown to illustrate the trap.
public long nCrNaive(int n, int r) {
    if (r < 0 || r > n) return 0;
    long num = 1, den = 1;
    for (int i = 0; i < r; i++) {
        num *= (n - i);   // overflows quickly for large n
        den *= (i + 1);
    }
    return num / den;     // plain division — cannot be made modular
}

