# Python big ints avoid overflow, but division still isn't modular.
def n_cr_naive(self, n: int, r: int) -> int:
    if r < 0 or r > n:
        return 0
    num = den = 1
    for i in range(r):
        num *= (n - i)
        den *= (i + 1)
    return num // den   # exact here, but (a/b) mod p != (a mod p)/(b mod p)

