import java.util.*;

class Binomial {
    private final long p;
    private final long[] fact, invFact;

    Binomial(int maxN, long p) {
        this.p = p;
        fact = new long[maxN + 1];
        invFact = new long[maxN + 1];
        fact[0] = 1;
        for (int i = 1; i <= maxN; i++) {
            fact[i] = fact[i - 1] * i % p;     // forward, mod after each multiply
        }
        invFact[maxN] = modpow(fact[maxN], p - 2, p); // one Fermat inverse
        for (int i = maxN - 1; i >= 0; i--) {
            invFact[i] = invFact[i + 1] * (i + 1) % p; // backward sweep
        }
    }

    long nCr(int n, int r) {
        if (r < 0 || r > n) return 0;
        return fact[n] * invFact[r] % p * invFact[n - r] % p;
    }

    private long modpow(long base, long exp, long mod) {
        long result = 1 % mod;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) result = result * base % mod;
            base = base * base % mod;
            exp >>= 1;
        }
        return result;
    }
}

